import clsx from 'clsx'

import {type HeadingTag} from '../../types/Heading'
import {getProps} from '../../utils/getProps'
import {suffixClassName} from '../../utils/suffixClassName'
import {type HeadingProps, headingProps} from './heading.props'

const headingClassName = suffixClassName('sui-Heading')

/** @public */
export function Heading<T extends HeadingTag = 'h2'>({size = 2, ...props}: HeadingProps<T>) {
  const {as, children, className, style, ...rest} = getProps({size, ...props}, headingProps)
  const Component = as || 'h2'

  if (props.truncate && props.trim) {
    return (
      <Component
        className={clsx(
          headingClassName,
          className?.replace('sui-line-clamp', '').replace('sui-text-overflow', ''),
          'sui-weight-bold',
        )}
        style={style}
        data-ui="Heading"
        {...rest}
      >
        <span
          className={clsx(
            'sui-overflow-hidden',
            props.truncate === 1 ? 'sui-text-overflow' : 'sui-line-clamp',
          )}
        >
          {children}
        </span>
      </Component>
    )
  }

  return (
    <Component
      className={clsx(
        headingClassName,
        props.truncate && 'sui-overflow-hidden',
        'sui-weight-bold',
        className,
      )}
      style={style}
      data-ui="Heading"
      {...rest}
    >
      {children}
    </Component>
  )
}

export type {HeadingProps}
